        private static GameState NewGame(int size = 5, int players = 2)
            => new GameState(size, size, players) { CurrentPlayerIndex = 0 };

        private static void Place(GameState game, int x, int y)
            => game.SetSideOwnership(new Coordinate(x, y), game.CurrentPlayerIndex, out _);

        private static GameState SurvivalPosition(int players = 2)
        {
            var game = NewGame(5, players);
            game.SpotToSideOwnership[new Coordinate(0, 0)] = 0;
            game.SpotToSideOwnership[new Coordinate(1, 0)] = 0;
            Place(game, 2, 0);
            game.SpotToSideOwnership[new Coordinate(0, 2)] = 1;
            game.SpotToSideOwnership[new Coordinate(1, 2)] = 1;
            return game;
        }

        private static CascadeSearch Finish(CascadePosition position, SearchSettings settings, int slice = 113)
        {
            var search = new CascadeSearch(position, settings);
            while (!search.IsComplete) search.Step(slice);
            return search;
        }

