        public void SnapshotAndTransitionsMatchAuthoritativeGame(int size, int players)
        {
            // All players' hypothetical scores and every transition are checked,
            // including history masks. This is a differential test, not a copy of
            // the new scorer used as its own oracle.
            for (int seed = 0; seed < 12; seed++)
            {
                var random = new Random(seed + size * 100);
                var game = NewGame(size, players);
                var position = CascadePosition.Capture(game);
                for (int turn = 0; turn < size * size && !position.IsTerminal; turn++)
                {
                    var moves = game.GetEmptySpots();
                    foreach (var move in moves)
                        for (int p = 0; p < players; p++)
                            Assert.AreEqual(HypotheticalSolutionTool.GetSolutionsFromClaimingTile(game, move, p).Count,
                                position.CountConnections(position.IndexOf(move), p),
                                $"score seed={seed}, turn={turn}, player={p}, move={move}");
                    var chosen = moves[random.Next(moves.Count)];
                    // Half of games deliberately seek scoring/survival to exercise
                    // consumed directions and elimination rather than only quiet draws.
                    if ((seed & 1) == 0)
