                    game.SetSideOwnership(chosen, game.CurrentPlayerIndex, out var solutions);
                    Assert.AreEqual(solutions.Count, count);
                    Assert.AreEqual(CascadePosition.Capture(game).Fingerprint(), position.Fingerprint(),
                        $"transition seed={seed}, turn={turn}");
                }
                Assert.IsTrue(position.IsTerminal);
            }
