        [Test]
        public void TinyTwoPlayerPositionsMatchExhaustiveIndependentMinimax()
        {
            int checkedPositions = 0;
            for (int seed = 0; seed < 40; seed++)
            {
                var game = NewGame(3);
                var random = new Random(seed);
                var history = new List<Coordinate>();
                for (int turn = 0; turn < 4 && game.CurrentGameState != GameState.GameStateEnum.End; turn++)
                {
                    var moves = game.GetEmptySpots();
                    var move = moves[random.Next(moves.Count)];
                    history.Add(move);
                    game.SetSideOwnership(move, game.CurrentPlayerIndex, out _);
                }
                if (game.CurrentGameState == GameState.GameStateEnum.End) continue;
                int rootPlayer = game.CurrentPlayerIndex;
                double optimal = ReferenceMinimax(history, rootPlayer);
                using (var search = Finish(CascadePosition.Capture(game),
                    new SearchSettings { MaxWorkUnits = 100000, RootChoiceNoise = 1 }))
                {
                    Assert.IsTrue(search.IsProven);
                    Assert.AreEqual(SearchStopReason.Solved, search.StopReason);
                    history.Add(search.BestMove.Value);
                    Assert.AreEqual(optimal, ReferenceMinimax(history, rootPlayer), $"seed={seed}");
                }
                checkedPositions++;
            }
            Assert.GreaterOrEqual(checkedPositions, 20);
        }

        private static double ReferenceMinimax(List<Coordinate> history, int rootPlayer)
        {
            // Independent, deliberately slow oracle: rebuild and replay the actual
            // GameState on every branch. Does not use CascadePosition or pruning.
            var game = NewGame(3);
            foreach (var move in history) game.SetSideOwnership(move, game.CurrentPlayerIndex, out _);
            if (game.CurrentGameState == GameState.GameStateEnum.End)
                return game.Winner.HasValue ? (game.Winner.Value == rootPlayer ? 1 : 0) : .5;
            bool maximizing = game.CurrentPlayerIndex == rootPlayer;
            double value = maximizing ? double.NegativeInfinity : double.PositiveInfinity;
            foreach (var move in game.GetEmptySpots())
            {
                history.Add(move);
                double child = ReferenceMinimax(history, rootPlayer);
                history.RemoveAt(history.Count - 1);
                value = maximizing ? Math.Max(value, child) : Math.Min(value, child);
            }
            return value;
        }

