        [Test]
        public void SharedComplexityScalingKeepsStrengthBudgetsOrdered()
        {
            foreach (int cells in new[] { 9, 25, 64, 144, 400 })
                foreach (int players in new[] { 2, 3, 6 })
                {
                    int easy = SearchSettings.ForPosition(CpuStrength.Easy, cells, players).MaxWorkUnits;
                    int normal = SearchSettings.ForPosition(CpuStrength.Normal, cells, players).MaxWorkUnits;
                    int hard = SearchSettings.ForPosition(CpuStrength.Hard, cells, players).MaxWorkUnits;
                    Assert.Less(easy, normal);
                    Assert.Less(normal, hard);
                }
        }

